"use strict";const t=[[/餐饮|吃|饭|外卖|美食|聚餐|零食|饮|咖啡|奶茶/,"🍜"],[/交通|地铁|公交|打车|出行|车|油|加油|停车|高铁/,"🚇"],[/购物|买|衣|鞋|服饰|数码|电器|日用/,"🛍️"],[/娱乐|游戏|电影|玩|唱|运动|健身/,"🎮"],[/居住|房租|房贷|物业|水电|燃气|家居/,"🏠"],[/医疗|药|医院|健康|体检/,"💊"],[/教育|学习|书|培训|课|学费/,"📚"],[/通讯|话费|网费|流量|手机|宽带/,"📱"],[/旅行|旅游|酒店|机票|景点/,"✈️"],[/宠物/,"🐾"],[/工资|薪|奖金|报销|劳务/,"💰"],[/理财|利息|收益|投资|分红|基金|股票/,"📈"],[/红包|礼金|转赠/,"🧧"],[/退款|返现/,"💸"]];const n=["周日","周一","周二","周三","周四","周五","周六"];exports.categoryEmoji=function(n,e){const r=String(n??"");for(const[o,i]of t)if(o.test(r))return i;return"income"===e?"💰":"🧾"},exports.currentMonth=function(){const t=new Date;return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}`},exports.dayKeyOf=function(t){return String(t||"").slice(0,10)},exports.dayLabel=function(t){const[e,r,o]=String(t).split("-").map(Number),i=new Date(e||1970,(r||1)-1,o||1).getDay();return`${r}月${o}日 ${n[i]??""}`},exports.formatAmount=function(t){const n="number"==typeof t?t:Number(t);if(!Number.isFinite(n))return"0.00";const e=n<0,r=Math.abs(n).toFixed(2),[o,i]=r.split(".");return(e?"-":"")+o.replace(/\B(?=(\d{3})+(?!\d))/g,",")+"."+i},exports.monthLabel=function(t){const[n,e]=String(t).split("-");return`${n}年${Number(e)}月`},exports.timeLabelOf=function(t){return String(t||"").slice(11,16)};
